#!/usr/bin/env python3
"""Remove executable JavaScript from an HTML file, retaining safe markup verbatim."""

import html
import re
import sys
from html.parser import HTMLParser

# Elements whose contents are either executable or can introduce a new document.
DROP_ELEMENTS = {
    "script", "iframe", "object", "embed", "applet", "frame", "frameset",
    # SVG and MathML have a number of less obvious script-injection mechanisms.
    "svg", "math",
}
VOID_ELEMENTS = {
    "area", "base", "br", "col", "embed", "hr", "img", "input", "link",
    "meta", "param", "source", "track", "wbr",
}
URI_ATTRIBUTES = {
    "href", "src", "action", "formaction", "cite", "background", "poster",
    "profile", "usemap", "longdesc", "dynsrc", "lowsrc", "ping", "xlink:href",
}
ATTR_RE = re.compile(r"(?is)(javascript|vbscript)\s*:|data\s*:\s*", re.I)
CSS_BAD_RE = re.compile(
    r"(?is)expression\s*\(|-moz-binding\s*:|behavior\s*:|"
    r"url\s*\(\s*['\"]?\s*(?:javascript|vbscript|data\s*:)")


def _attributes(raw):
    """Yield (start, end, lower-name, value) for attributes in a raw start tag."""
    n = len(raw)
    i = 1
    while i < n and raw[i].isspace():
        i += 1
    while i < n and not raw[i].isspace() and raw[i] not in "/>":
        i += 1                         # element name
    while i < n:
        while i < n and raw[i].isspace():
            i += 1
        if i >= n or raw[i] == ">":
            break
        if raw[i] == "/":
            i += 1
            continue
        start = i
        while i < n and not raw[i].isspace() and raw[i] not in "=/>":
            i += 1
        name = raw[start:i].lower()
        while i < n and raw[i].isspace():
            i += 1
        value = ""
        if i < n and raw[i] == "=":
            i += 1
            while i < n and raw[i].isspace():
                i += 1
            if i < n and raw[i] in "\"'":
                quote = raw[i]
                i += 1
                vstart = i
                while i < n and raw[i] != quote:
                    i += 1
                value = raw[vstart:i]
                if i < n:
                    i += 1
            else:
                vstart = i
                while i < n and not raw[i].isspace() and raw[i] != ">":
                    i += 1
                value = raw[vstart:i]
        yield start, i, name, value


def safe_start_tag(raw):
    """Return raw unchanged, or remove only attributes which can execute code."""
    attrs = list(_attributes(raw))
    remove = []
    http_equiv = content = ""
    for start, end, name, value in attrs:
        decoded = html.unescape(value).replace("\x00", "").strip().lower()
        compact = re.sub(r"[\x00-\x20]+", "", decoded)
        if name.startswith("on") or name == "srcdoc":
            remove.append((start, end))
        elif name in URI_ATTRIBUTES and (ATTR_RE.search(decoded) or compact.startswith(("javascript:", "vbscript:", "data:"))):
            remove.append((start, end))
        elif name == "style" and CSS_BAD_RE.search(decoded):
            remove.append((start, end))
        elif name == "http-equiv":
            http_equiv = decoded
        elif name == "content":
            content = decoded
    if http_equiv == "refresh" and (ATTR_RE.search(content) or "javascript" in content):
        for start, end, name, value in attrs:
            if name == "content":
                remove.append((start, end))
    if not remove:
        return raw
    # Include the whitespace immediately before an attribute, but do not touch
    # any other bytes (quotes, newlines, and indentation are otherwise kept).
    pieces = []
    last = 0
    for start, end in sorted(set(remove)):
        while start > 1 and raw[start - 1].isspace():
            start -= 1
        pieces.append(raw[last:start])
        last = end
    pieces.append(raw[last:])
    return "".join(pieces)


class Filter(HTMLParser):
    def __init__(self):
        super().__init__(convert_charrefs=False)
        self.out = []
        self.dropped = []
        self.style_depth = 0

    def handle_starttag(self, tag, attrs):
        tag = tag.lower()
        raw = self.get_starttag_text()
        if self.dropped:
            if tag not in VOID_ELEMENTS:
                self.dropped.append(tag)
            return
        if tag in DROP_ELEMENTS:
            if tag not in VOID_ELEMENTS and not raw.rstrip().endswith("/>"):
                self.dropped.append(tag)
            return
        self.out.append(safe_start_tag(raw))
        if tag == "style":
            self.style_depth += 1

    def handle_startendtag(self, tag, attrs):
        if not self.dropped and tag.lower() not in DROP_ELEMENTS:
            self.out.append(safe_start_tag(self.get_starttag_text()))

    def handle_endtag(self, tag):
        tag = tag.lower()
        if self.dropped:
            if tag == self.dropped[-1]:
                self.dropped.pop()
            return
        self.out.append(f"</{tag}>")
        if tag == "style" and self.style_depth:
            self.style_depth -= 1

    def handle_data(self, data):
        if not self.dropped:
            if self.style_depth:
                data = re.sub(r"(?is)(javascript|vbscript)\s*:", "", data)
                data = re.sub(r"(?is)expression\s*\(", "(", data)
            self.out.append(data)

    def handle_entityref(self, name):
        if not self.dropped:
            self.out.append("&" + name + ";")

    def handle_charref(self, name):
        if not self.dropped:
            self.out.append("&#" + name + ";")

    def handle_comment(self, data):
        if not self.dropped:
            self.out.append("<!--" + data + "-->")

    def handle_decl(self, decl):
        if not self.dropped:
            self.out.append("<" + decl + ">")

    def unknown_decl(self, data):
        if not self.dropped:
            self.out.append("<![" + data + "]>")

    def handle_pi(self, data):
        if not self.dropped:
            self.out.append("<?" + data + ">")


def main():
    path = sys.argv[1]
    with open(path, "r", encoding="utf-8", errors="surrogateescape", newline="") as f:
        source = f.read()
    parser = Filter()
    parser.feed(source)
    parser.close()
    with open(path, "w", encoding="utf-8", errors="surrogateescape", newline="") as f:
        f.write("".join(parser.out))


if __name__ == "__main__":
    main()

